import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 0.99, D: 33.33, E: 100, F: 100.01 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function totalFor(items) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  try {
    const res = await fetch(`http://localhost:${server.address().port}/orders`, {
      method: 'POST', body: JSON.stringify({ items }),
    })
    assert.equal(res.status, 201)
    return (await res.json()).total
  } finally { server.close() }
}

// Characterization tests: they pin current behaviour, including the questionable parts.
test('sums unit price * qty across items', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 3 }]), 95)
})

test('no discount at exactly 100', async () => {
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }]), 100)
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('10% discount when total is over 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99)   // 110 -> 99
  assert.equal(await totalFor([{ sku: 'B', qty: 8 }]), 180)   // 200 -> 180
  assert.equal(await totalFor([{ sku: 'E', qty: 10 }]), 900)  // 1000 -> 900
})

test('discount is flat, not tiered, for larger orders', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 1000 }]), 9000)
})

test('total is floored to whole euros (cents dropped)', async () => {
  assert.equal(await totalFor([{ sku: 'C', qty: 3 }]), 2)       // 2.97 -> 2, not 3
  assert.equal(await totalFor([{ sku: 'D', qty: 3 }]), 99)      // 99.99 -> 99
  assert.equal(await totalFor([{ sku: 'F', qty: 1 }]), 90)      // 100.01 -> 90.009 -> 90
})

test('floating point: discounted totals can land just under an integer', async () => {
  // 0.1 * 1100 style errors: 3 * 33.34 = 100.02 -> 90.018 -> 90
  prices.G = 33.34
  assert.equal(await totalFor([{ sku: 'G', qty: 3 }]), 90)
  // 110 - 11 = 99 exactly here, but 0.1 multiples are inexact in binary
  prices.H = 1.1
  assert.equal(await totalFor([{ sku: 'H', qty: 100 }]), 99)
})
EOF
